BEGIN
 NEW.record_revision:=OLD.record_revision;
 NEW.authority_revision:=OLD.authority_revision;
 NEW.grant_revision:=OLD.grant_revision;
 IF ROW(NEW.attempt_id,NEW.task_id,NEW.node_id,NEW.offer_id,NEW.session_id,NEW.kind)
    IS DISTINCT FROM ROW(OLD.attempt_id,OLD.task_id,OLD.node_id,OLD.offer_id,OLD.session_id,OLD.kind)
 THEN RAISE EXCEPTION 'immutable execution identity' USING ERRCODE='23514'; END IF;
 IF OLD.kind='legacy_fixture' AND
   (NEW.state->'offer'->'identity' IS DISTINCT FROM OLD.state->'offer'->'identity'
    OR NEW.state->'offer'->'attempt' IS DISTINCT FROM OLD.state->'offer'->'attempt')
 THEN RAISE EXCEPTION 'immutable legacy boot/generation' USING ERRCODE='23514'; END IF;
 IF OLD.kind='profiled_v1' AND
   (NEW.state->'offer' IS DISTINCT FROM OLD.state->'offer'
    OR NEW.state->'source' IS DISTINCT FROM OLD.state->'source'
    OR NEW.state->'graph' IS DISTINCT FROM OLD.state->'graph')
 THEN RAISE EXCEPTION 'immutable profiled launch' USING ERRCODE='23514'; END IF;
 IF OLD.execution_deadline_ms IS NOT NULL AND NEW.execution_deadline_ms IS DISTINCT FROM OLD.execution_deadline_ms
 THEN RAISE EXCEPTION 'immutable execution deadline' USING ERRCODE='23514'; END IF;
 IF NEW.state IS DISTINCT FROM OLD.state OR NEW.holds_task IS DISTINCT FROM OLD.holds_task
 THEN NEW.record_revision:=OLD.record_revision+1; END IF;
 IF NEW.state->'status' IS DISTINCT FROM OLD.state->'status'
   OR NEW.state->'cancellation_id' IS DISTINCT FROM OLD.state->'cancellation_id'
   OR NEW.state->'revoked' IS DISTINCT FROM OLD.state->'revoked'
   OR NEW.state->'stopped' IS DISTINCT FROM OLD.state->'stopped'
   OR NEW.state->'stop' IS DISTINCT FROM OLD.state->'stop'
   OR (NEW.kind='profiled_v1' AND NEW.state->'grant'->'grant_id' IS DISTINCT FROM OLD.state->'grant'->'grant_id')
 THEN NEW.authority_revision:=OLD.authority_revision+1; END IF;
 IF NEW.state->'grant' IS DISTINCT FROM OLD.state->'grant'
 THEN NEW.grant_revision:=OLD.grant_revision+1; END IF;
 RETURN NEW;
END

BEGIN
 IF TG_OP='TRUNCATE' THEN
  IF TG_TABLE_NAME='mailbox_messages' THEN
   IF EXISTS(SELECT 1 FROM mailbox_messages WHERE mailbox_key=central_global_mailbox_key() OR recipient->>'kind'='global_supervisor') THEN
    RAISE EXCEPTION 'global supervisor original mail cannot be truncated';
   END IF;
  ELSE
   IF EXISTS(SELECT 1 FROM mailbox_operations WHERE response->>'contract'='human-supervisor-conversation-1') THEN
    RAISE EXCEPTION 'global supervisor original receipts cannot be truncated';
   END IF;
  END IF;
  RETURN NULL;
 END IF;
 IF TG_TABLE_NAME='mailbox_messages' THEN
  IF OLD.mailbox_key=central_global_mailbox_key() OR OLD.recipient->>'kind'='global_supervisor'
   OR (TG_OP='UPDATE' AND (NEW.mailbox_key=central_global_mailbox_key() OR NEW.recipient->>'kind'='global_supervisor')) THEN
   RAISE EXCEPTION 'global supervisor original mail is immutable';
  END IF;
 ELSE
  IF OLD.response->>'contract'='human-supervisor-conversation-1'
   OR (TG_OP='UPDATE' AND NEW.response->>'contract'='human-supervisor-conversation-1') THEN
   RAISE EXCEPTION 'global supervisor original receipt is immutable';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END

DECLARE base execution_attempts%ROWTYPE; previous_status TEXT; current_status TEXT; current_stop TEXT;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'immutable hot authority adoption' USING ERRCODE='23514'; END IF;
 current_status:=NEW.state->>'status';
 current_stop:=COALESCE(NEW.state#>>'{stop,kind}','');
 IF NEW.state->>'schema_version' IS DISTINCT FROM '1'
    OR NOT (NEW.state ?& ARRAY['schema_version','status','grant','execution_deadline_ms','owner','cancellation_id','revoked','stop','retention','effects'])
    OR jsonb_typeof(NEW.state->'revoked') IS DISTINCT FROM 'boolean'
    OR current_status IS NULL OR current_status NOT IN ('offered','preparing','granted','cancelling','finished','declined','unknown','never_granted')
 THEN RAISE EXCEPTION 'invalid hot authority state' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
   SELECT * INTO STRICT base FROM execution_attempts WHERE attempt_id=NEW.attempt_id FOR UPDATE;
   IF base.kind<>'profiled_v1' THEN RAISE EXCEPTION 'profiled adoption only' USING ERRCODE='23514'; END IF;
   IF NEW.state - 'owner' IS DISTINCT FROM jsonb_build_object(
      'schema_version',base.state->'schema_version','status',base.state->'status',
      'grant',base.state->'grant','execution_deadline_ms',base.state->'execution_deadline_ms',
      'cancellation_id',base.state->'cancellation_id','revoked',base.state->'revoked',
      'stop',base.state->'stop','retention',base.state->'retention','effects',base.state->'effects')
      OR NEW.state->'owner' IS DISTINCT FROM 'null'::jsonb
      OR NEW.state->'grant' IS DISTINCT FROM 'null'::jsonb
   THEN RAISE EXCEPTION 'adoption must preserve actual compatibility authority without inventing owner' USING ERRCODE='23514'; END IF;
   NEW.record_revision:=base.record_revision;
   NEW.authority_revision:=base.authority_revision;
   NEW.grant_revision:=base.grant_revision;
 ELSE
   -- The producer already owns node->attempt->hot locks. Do not acquire the
   -- attempt lock backwards from a raw UPDATE of hot; the common loader also
   -- checks holds_task freshly and refuses released active authority.
   SELECT * INTO STRICT base FROM execution_attempts WHERE attempt_id=OLD.attempt_id;
   previous_status:=OLD.state->>'status';
   IF NEW.attempt_id IS DISTINCT FROM OLD.attempt_id THEN RAISE EXCEPTION 'immutable hot attempt' USING ERRCODE='23514'; END IF;
   IF OLD.state->'execution_deadline_ms'<>'null'::jsonb AND NEW.state->'execution_deadline_ms' IS DISTINCT FROM OLD.state->'execution_deadline_ms'
   THEN RAISE EXCEPTION 'immutable hot hard deadline' USING ERRCODE='23514'; END IF;
   IF OLD.state->'owner'<>'null'::jsonb AND NEW.state->'owner' IS DISTINCT FROM OLD.state->'owner'
   THEN RAISE EXCEPTION 'immutable hot launch owner' USING ERRCODE='23514'; END IF;
   IF OLD.state->'revoked'='true'::jsonb AND NEW.state->'revoked'<>'true'::jsonb
   THEN RAISE EXCEPTION 'hot revocation is monotonic' USING ERRCODE='23514'; END IF;
   IF OLD.state->'cancellation_id'<>'null'::jsonb AND NEW.state->'cancellation_id' IS DISTINCT FROM OLD.state->'cancellation_id'
   THEN RAISE EXCEPTION 'immutable hot cancellation' USING ERRCODE='23514'; END IF;
   IF OLD.state#>>'{stop,kind}' IN ('not_started','stopped') AND NEW.state->'stop' IS DISTINCT FROM OLD.state->'stop'
   THEN RAISE EXCEPTION 'known stop cannot be undone or rewritten' USING ERRCODE='23514'; END IF;
   IF (previous_status IN ('finished','declined','never_granted') AND current_status<>previous_status)
      OR (previous_status IN ('cancelling','unknown') AND current_status IN ('offered','preparing','granted'))
      OR (previous_status='preparing' AND current_status='offered')
      OR (previous_status='granted' AND current_status IN ('offered','preparing','declined'))
   THEN RAISE EXCEPTION 'hot authority cannot reactivate' USING ERRCODE='23514'; END IF;
   IF OLD.state->'grant'<>'null'::jsonb THEN
     IF NEW.state->'grant'='null'::jsonb OR (NEW.state->'grant')-'expires_at_ms' IS DISTINCT FROM (OLD.state->'grant')-'expires_at_ms'
     THEN RAISE EXCEPTION 'issued grant identity and binding immutable' USING ERRCODE='23514'; END IF;
     IF NEW.state->'grant' IS DISTINCT FROM OLD.state->'grant'
        AND (previous_status<>'granted' OR current_status<>'granted' OR NEW.state->'revoked'<>'false'::jsonb OR NEW.state->'cancellation_id'<>'null'::jsonb)
     THEN RAISE EXCEPTION 'renewal requires current live granted status' USING ERRCODE='23514'; END IF;
   ELSIF NEW.state->'grant'<>'null'::jsonb AND (previous_status<>'preparing' OR current_status<>'granted')
   THEN RAISE EXCEPTION 'first grant requires durable preparation' USING ERRCODE='23514'; END IF;
   NEW.record_revision:=OLD.record_revision;
   NEW.authority_revision:=OLD.authority_revision;
   NEW.grant_revision:=OLD.grant_revision;
   IF NEW.state IS DISTINCT FROM OLD.state THEN NEW.record_revision:=OLD.record_revision+1; END IF;
   IF ROW(NEW.state->'status',NEW.state->'owner',NEW.state->'cancellation_id',NEW.state->'revoked',NEW.state->'stop',NEW.state->'execution_deadline_ms',NEW.state->'grant'->'grant_id')
      IS DISTINCT FROM ROW(OLD.state->'status',OLD.state->'owner',OLD.state->'cancellation_id',OLD.state->'revoked',OLD.state->'stop',OLD.state->'execution_deadline_ms',OLD.state->'grant'->'grant_id')
   THEN NEW.authority_revision:=OLD.authority_revision+1; END IF;
   IF NEW.state->'grant' IS DISTINCT FROM OLD.state->'grant' THEN NEW.grant_revision:=OLD.grant_revision+1; END IF;
 END IF;
 IF (current_status='never_granted' AND (NEW.state->'grant'<>'null'::jsonb OR current_stop<>'unknown' OR NOT EXISTS(SELECT 1 FROM profiled_never_granted_closures WHERE attempt_id=NEW.attempt_id)))
    OR (current_status='offered' AND (NEW.state->'owner'<>'null'::jsonb OR NEW.state->'grant'<>'null'::jsonb OR current_stop<>'unknown'))
    OR (current_status='preparing' AND (jsonb_typeof(NEW.state->'owner') IS DISTINCT FROM 'object' OR NEW.state->'grant'<>'null'::jsonb OR current_stop<>'unknown'))
    OR (current_status IN ('finished','declined') AND current_stop NOT IN ('not_started','stopped'))
    OR (current_status='declined' AND NEW.state->'grant'<>'null'::jsonb)
    OR (current_stop IN ('not_started','stopped') AND (jsonb_typeof(NEW.state->'owner') IS DISTINCT FROM 'object' OR current_status IN ('offered','preparing','granted')))
    OR (current_status='granted' AND (NOT base.holds_task OR NEW.state->'revoked'<>'false'::jsonb OR NEW.state->'cancellation_id'<>'null'::jsonb OR current_stop NOT IN ('unknown','running')
        OR jsonb_typeof(NEW.state->'owner') IS DISTINCT FROM 'object' OR jsonb_typeof(NEW.state->'grant') IS DISTINCT FROM 'object'
        OR COALESCE((NEW.state->>'execution_deadline_ms')::BIGINT,0)<=0
        OR COALESCE((NEW.state#>>'{grant,expires_at_ms}')::BIGINT,0)<=0
        OR (NEW.state#>>'{grant,expires_at_ms}')::BIGINT>(NEW.state->>'execution_deadline_ms')::BIGINT))
 THEN RAISE EXCEPTION 'inconsistent hot status/claim/owner' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END

BEGIN
 IF EXISTS(SELECT 1 FROM profiled_launch_closures WHERE attempt_id=NEW.attempt_id) AND (NOT NEW.revoked OR NEW.credential_verifier IS NOT NULL OR NEW.credential_expires_at_ms IS NOT NULL) THEN RAISE EXCEPTION 'closed launch cannot issue credentials'; END IF;
 RETURN NEW;
END

BEGIN
 IF EXISTS(SELECT 1 FROM profiled_launch_closures WHERE attempt_id=NEW.attempt_id) AND (NEW.state->>'status'='granted' OR NEW.state->>'revoked' IS DISTINCT FROM 'true' OR NEW.state->'grant' IS DISTINCT FROM OLD.state->'grant' OR NEW.state->'owner' IS DISTINCT FROM OLD.state->'owner') THEN RAISE EXCEPTION 'terminal launch closure cannot reopen'; END IF;
 RETURN NEW;
END

DECLARE phase BOOLEAN;
BEGIN
 phase:=EXISTS(SELECT 1 FROM profiled_v2_accepts WHERE attempt_id=NEW.attempt_id) OR EXISTS(SELECT 1 FROM profiled_phase_execution_grants WHERE attempt_id=NEW.attempt_id);
 -- Release remains a separate closed authority boundary, including new writers.
 IF TG_TABLE_NAME='profiled_verified_releases' THEN
  IF phase THEN RAISE EXCEPTION 'phase settlement protocol not qualified' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF phase THEN
  IF current_setting('transaction_isolation') NOT IN ('read committed','serializable')
   OR NOT profiled_result_origin_valid(NEW.attempt_id,NEW.node_id,NEW.result_origin_kind,NEW.origin_execution_receipt_digest,NEW.origin_stopped_ack_bytes_digest)
   OR current_setting('aq.result_origin',true) IS DISTINCT FROM 'aq.result-origin.1:'||NEW.result_origin_kind||':'||NEW.origin_execution_receipt_digest||':'||NEW.origin_stopped_ack_bytes_digest
  THEN RAISE EXCEPTION 'qualified exact phase result origin required' USING ERRCODE='23514'; END IF;
 ELSIF NEW.result_origin_kind<>'legacy_prepare_v1' OR NEW.origin_execution_receipt_digest IS NOT NULL OR NEW.origin_stopped_ack_bytes_digest IS NOT NULL THEN
  RAISE EXCEPTION 'legacy result cannot claim phase origin' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END

BEGIN
 IF NOT EXISTS(SELECT 1 FROM profiled_result_heads WHERE attempt_id=NEW.attempt_id AND report_id=NEW.report_id)
 THEN RAISE EXCEPTION 'report and correction head must commit together'; END IF;
 RETURN NULL;
END

DECLARE previous UUID; owner UUID;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'retained result head'; END IF;
 SELECT attempt_id,supersedes INTO STRICT owner,previous FROM profiled_result_reports WHERE report_id=NEW.report_id;
 IF NEW.attempt_id<>owner THEN RAISE EXCEPTION 'result head scope'; END IF;
 IF TG_OP='INSERT' THEN
  IF previous IS NOT NULL THEN RAISE EXCEPTION 'first report head cannot skip predecessor'; END IF;
 ELSE
  IF NEW.attempt_id<>OLD.attempt_id OR previous IS DISTINCT FROM OLD.report_id OR NEW.report_id=OLD.report_id
  THEN RAISE EXCEPTION 'result correction must follow current head'; END IF;
 END IF;
 RETURN NEW;
END

DECLARE q JSONB; r JSONB; b JSONB; m JSONB; s JSONB; stopped JSONB;
 h JSONB; held BOOLEAN; head UUID; n BIGINT; used BIGINT; a admission_artifacts%ROWTYPE;
BEGIN
 -- Also serialize direct owner inserts; no authority fields are changed.
 SELECT holds_task INTO STRICT held FROM execution_attempts WHERE attempt_id=NEW.attempt_id FOR UPDATE;
 SELECT state INTO STRICT h FROM profiled_authority_hot WHERE attempt_id=NEW.attempt_id;
 SELECT launch_binding,launch_manifest INTO STRICT b,m FROM profiled_launches WHERE attempt_id=NEW.attempt_id;
 SELECT convert_from(request_bytes,'UTF8')::JSONB,
 jsonb_build_object('id','aq.native-stopped/'||NEW.attempt_id::TEXT,'version','1','digest',encode(sha256(receipt_bytes),'hex'))
 INTO STRICT s,stopped FROM profiled_stopped_receipts WHERE attempt_id=NEW.attempt_id;
 SELECT * INTO STRICT a FROM admission_artifacts WHERE artifact_id=NEW.outcome_artifact_id;
 q:=convert_from(NEW.report_bytes,'UTF8')::JSONB;r:=convert_from(NEW.receipt_bytes,'UTF8')::JSONB;
 SELECT report_id INTO head FROM profiled_result_heads WHERE attempt_id=NEW.attempt_id;
 SELECT count(*),COALESCE(sum(octet_length(report_bytes)),0) INTO n,used FROM profiled_result_reports WHERE attempt_id=NEW.attempt_id;
 IF NOT held OR h->>'status' IS DISTINCT FROM 'finished'
 OR h->'stop' IS DISTINCT FROM jsonb_build_object('kind','stopped','receipt',stopped)
 OR q->>'schema_version' IS DISTINCT FROM '1' OR r->>'schema_version' IS DISTINCT FROM '1'
 OR q->'binding' IS DISTINCT FROM b OR r->'binding' IS DISTINCT FROM b
 OR q#>>'{identity,node_id}' IS DISTINCT FROM NEW.node_id::TEXT
 OR q#>>'{identity,boot_id}' IS DISTINCT FROM b#>>'{session,boot_id}'
 OR b#>>'{session,node_id}' IS DISTINCT FROM NEW.node_id::TEXT
 OR q->>'operation_id' IS DISTINCT FROM NEW.operation_id::TEXT OR r->>'operation_id' IS DISTINCT FROM NEW.operation_id::TEXT
 OR q->>'report_id' IS DISTINCT FROM NEW.report_id::TEXT OR r->>'report_id' IS DISTINCT FROM NEW.report_id::TEXT
 OR (q->>'supersedes')::UUID IS DISTINCT FROM NEW.supersedes OR NEW.supersedes IS DISTINCT FROM head
 OR q->'stop' IS DISTINCT FROM s->'evidence'
 OR r->>'report_digest' IS DISTINCT FROM NEW.report_digest
 OR r->>'disposition' IS DISTINCT FROM 'recorded'
 OR r->'stopped_receipt' IS DISTINCT FROM stopped
 OR r->'expected_outcome' IS DISTINCT FROM m#>'{bindings,outcome}'
 OR COALESCE((r->>'recorded_at_ms')::BIGINT,0)<=0
 OR a.owner_kind<>'outcome' OR a.owner_key IS DISTINCT FROM m#>>'{bindings,project_id}'
 OR a.descriptor->'artifact' IS DISTINCT FROM m#>'{bindings,outcome}' OR a.body IS NULL
 OR NOT EXISTS(SELECT 1 FROM profiled_launch_artifacts WHERE attempt_id=NEW.attempt_id AND artifact_id=NEW.outcome_artifact_id)
 OR n>=64 OR used+octet_length(NEW.report_bytes)>4194304
 THEN RAISE EXCEPTION 'native report requires exact stopped/outcome owner, correction head and quota'; END IF;
 RETURN NEW;
END

BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'sealed admission record cannot be deleted' USING ERRCODE='23514'; END IF;
 IF NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'sealed admission record cannot change' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END

BEGIN
 IF ROW(NEW.subject_digest,NEW.report_id,NEW.project_id,NEW.workspace_id,NEW.task_id,NEW.sealed_version,NEW.key_id,NEW.nonce,NEW.ciphertext)
 IS DISTINCT FROM ROW(OLD.subject_digest,OLD.report_id,OLD.project_id,OLD.workspace_id,OLD.task_id,OLD.sealed_version,OLD.key_id,OLD.nonce,OLD.ciphertext)
 THEN RAISE EXCEPTION 'immutable review subject'; END IF;
 RETURN NEW;
END

BEGIN
 IF NEW.disposition='accepted' AND NOT EXISTS(SELECT 1 FROM profiled_verified_releases r JOIN profiled_task_completions c USING(attempt_id,release_id) WHERE r.attempt_id=NEW.attempt_id AND r.release_id=NEW.release_id AND r.settlement_operation_id=NEW.operation_id AND c.evaluation_operation_id=NEW.operation_id AND c.operation_id::TEXT=NEW.receipt->>'completion_operation_id') THEN RAISE EXCEPTION 'accepted evaluation/release/completion must commit together'; END IF;
 RETURN NULL;
END

BEGIN
 IF OLD.kind='profiled_v1' AND OLD.holds_task AND NOT NEW.holds_task AND EXISTS(SELECT 1 FROM profiled_authority_hot WHERE attempt_id=OLD.attempt_id)
 AND NOT EXISTS(SELECT 1 FROM profiled_task_completions c JOIN profiled_settlement_evaluations e ON e.operation_id=c.evaluation_operation_id JOIN profiled_verified_releases r ON r.attempt_id=c.attempt_id AND r.release_id=c.release_id WHERE c.attempt_id=OLD.attempt_id AND c.state='confirmed' AND e.disposition='accepted' AND e.operation_id=r.settlement_operation_id AND c.receipt IS NOT NULL AND c.outbox IS NOT NULL)
 THEN RAISE EXCEPTION 'claim remains held until actual Graph completion receipt'; END IF;
 RETURN NEW;
END

DECLARE e profiled_settlement_evaluations%ROWTYPE; l JSONB; p JSONB;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'retained completion intent'; END IF;
 IF current_setting('aq.settlement_owner',true) IS DISTINCT FROM 'aq.settlement-owner.1' THEN RAISE EXCEPTION 'actual completion owner required'; END IF;
 SELECT * INTO STRICT e FROM profiled_settlement_evaluations WHERE operation_id=NEW.evaluation_operation_id;
 SELECT execution_spec INTO STRICT l FROM profiled_launches WHERE attempt_id=NEW.attempt_id;
 p:=convert_from(NEW.payload_bytes,'UTF8')::JSONB;
 IF e.disposition<>'accepted' OR e.attempt_id<>NEW.attempt_id OR e.release_id<>NEW.release_id OR e.receipt->>'completion_operation_id' IS DISTINCT FROM NEW.operation_id::TEXT
 OR NEW.workspace_id::TEXT IS DISTINCT FROM l#>>'{task,workspace_id}' OR NEW.task_id::TEXT IS DISTINCT FROM l#>>'{task,task_id}'
 OR NEW.expected_version::TEXT IS DISTINCT FROM l#>>'{task,version}' OR NEW.expected_content_revision::TEXT IS DISTINCT FROM l#>>'{task,content_revision}'
 OR p IS DISTINCT FROM jsonb_build_object('idempotency_key','aq-settlement-v1:'||NEW.operation_id::TEXT,'reason','Human-reviewed retained result '||e.report_id::TEXT,'operations',jsonb_build_array(jsonb_build_object('op','update_node','id',NEW.task_id,'expected_version',NEW.expected_version,'patch',jsonb_build_object('task_state','completed'))))
 THEN RAISE EXCEPTION 'completion cannot retarget accepted original task'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'prepared' OR NEW.dispatch_count<>0 OR NEW.receipt IS NOT NULL OR NEW.outbox IS NOT NULL OR NEW.lease_id IS NOT NULL THEN RAISE EXCEPTION 'new completion must be undispatched'; END IF;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['state','dispatch_count','lease_id','lease_expires_at_ms','receipt','outbox','outbox_acknowledged']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','dispatch_count','lease_id','lease_expires_at_ms','receipt','outbox','outbox_acknowledged'])
   OR NEW.dispatch_count<OLD.dispatch_count OR NEW.dispatch_count>OLD.dispatch_count+1
   OR (OLD.outbox_acknowledged AND NOT NEW.outbox_acknowledged)
   OR (OLD.state IN ('confirmed','conflict','blocked') AND (to_jsonb(NEW)-'outbox_acknowledged') IS DISTINCT FROM (to_jsonb(OLD)-'outbox_acknowledged'))
   OR (NEW.dispatch_count=OLD.dispatch_count+1 AND (NEW.state<>'possible' OR NEW.lease_id IS NULL OR NEW.lease_expires_at_ms IS NULL))
   OR (NEW.dispatch_count=OLD.dispatch_count AND NEW.lease_id IS NOT NULL AND ROW(NEW.lease_id,NEW.lease_expires_at_ms) IS DISTINCT FROM ROW(OLD.lease_id,OLD.lease_expires_at_ms))
   OR (NEW.state IN ('confirmed','conflict') AND (OLD.state<>'possible' OR OLD.lease_id IS NULL OR NEW.lease_id IS NOT NULL))
  THEN RAISE EXCEPTION 'completion transition or immutable intent changed'; END IF;
 END IF;
 IF NEW.state='confirmed' AND (NEW.receipt->>'workspace_id' IS DISTINCT FROM NEW.workspace_id::TEXT OR NEW.receipt->>'task_id' IS DISTINCT FROM NEW.task_id::TEXT
  OR NEW.receipt->>'version' IS DISTINCT FROM (NEW.expected_version+1)::TEXT OR NEW.receipt->>'content_revision' IS DISTINCT FROM (NEW.expected_content_revision+1)::TEXT
  OR COALESCE(NEW.receipt->>'change_set_id','') !~ '^[0-9a-f-]{36}$' OR COALESCE(NEW.receipt->>'response_digest','') !~ '^[0-9a-f]{64}$'
  OR NEW.outbox->>'event_id' IS DISTINCT FROM NEW.operation_id::TEXT OR NEW.outbox->>'producer' IS DISTINCT FROM 'aq.task.settlement@1'
  OR NEW.outbox->>'event' IS DISTINCT FROM 'task.completed' OR NEW.outbox->>'attempt_id' IS DISTINCT FROM NEW.attempt_id::TEXT
  OR NEW.outbox->>'evaluation_operation_id' IS DISTINCT FROM NEW.evaluation_operation_id::TEXT OR NEW.outbox->'report' IS DISTINCT FROM e.receipt->'report'
  OR NEW.outbox->>'release_id' IS DISTINCT FROM NEW.release_id::TEXT OR NEW.outbox->'receipt' IS DISTINCT FROM NEW.receipt)
 THEN RAISE EXCEPTION 'completion receipt/outbox must match actual original task'; END IF;
 RETURN NEW;
END

DECLARE r profiled_result_reports%ROWTYPE; s source_transfers%ROWTYPE; d human_decision_requests%ROWTYPE; h JSONB; n BIGINT; used BIGINT;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'immutable retained settlement evaluation'; END IF;
 IF current_setting('aq.settlement_owner',true) IS DISTINCT FROM 'aq.settlement-owner.1' THEN RAISE EXCEPTION 'actual settlement owner required'; END IF;
 SELECT * INTO STRICT r FROM profiled_result_reports WHERE report_id=NEW.report_id;
 SELECT * INTO STRICT s FROM source_transfers WHERE import_operation_id=NEW.source_operation_id;
 SELECT * INTO STRICT d FROM human_decision_requests WHERE decision_id=NEW.decision_id;
 SELECT state INTO STRICT h FROM profiled_authority_hot WHERE attempt_id=NEW.attempt_id;
 SELECT count(*) INTO n FROM profiled_settlement_evaluations WHERE attempt_id=NEW.attempt_id;
 SELECT COALESCE(sum(reserved_bytes),0) INTO used FROM profiled_settlement_evaluations;
 IF n>=16 OR used>67108864-196608 OR r.attempt_id<>NEW.attempt_id OR s.attempt_id<>NEW.attempt_id OR s.node_id<>r.node_id OR s.state<>'retained'
 OR h->>'status' IS DISTINCT FROM 'finished' OR h#>>'{stop,kind}' IS DISTINCT FROM 'stopped'
 OR NOT EXISTS(SELECT 1 FROM execution_attempts WHERE attempt_id=NEW.attempt_id AND holds_task)
 OR NOT EXISTS(SELECT 1 FROM profiled_result_heads WHERE attempt_id=NEW.attempt_id AND report_id=NEW.report_id)
 OR NOT EXISTS(SELECT 1 FROM review_subjects WHERE subject_digest=d.subject_digest AND report_id=NEW.report_id AND subject_profile='source_and_effects_review_v1')
 OR NEW.request->>'schema_version' IS DISTINCT FROM '1' OR NEW.request->>'operation_id' IS DISTINCT FROM NEW.operation_id::TEXT
 OR NEW.request->>'report_id' IS DISTINCT FROM NEW.report_id::TEXT OR NEW.request->>'source_operation_id' IS DISTINCT FROM NEW.source_operation_id::TEXT
 OR NEW.request->>'decision_id' IS DISTINCT FROM NEW.decision_id::TEXT OR NEW.request#>>'{subject,digest}' IS DISTINCT FROM d.subject_digest
 OR NEW.receipt->>'operation_id' IS DISTINCT FROM NEW.operation_id::TEXT OR NEW.receipt->>'attempt_id' IS DISTINCT FROM NEW.attempt_id::TEXT
 OR NEW.receipt->>'disposition' IS DISTINCT FROM NEW.disposition OR NEW.receipt->>'recorded_at_ms' IS DISTINCT FROM NEW.created_at_ms::TEXT
 OR NEW.receipt->>'release_id' IS DISTINCT FROM NEW.release_id::TEXT OR NEW.receipt->'subject' IS DISTINCT FROM NEW.request->'subject'
 OR NEW.receipt#>>'{report,id}' IS DISTINCT FROM 'aq.result-record/'||NEW.report_id::TEXT
 THEN RAISE EXCEPTION 'settlement owner cross-link, stopped basis or retained quota invalid'; END IF;
 RETURN NEW;
END

DECLARE a UUID;
BEGIN
 IF TG_OP='TRUNCATE' THEN
  IF EXISTS(SELECT 1 FROM profiled_settlement_evaluations) THEN RAISE EXCEPTION 'retained settlement basis cannot truncate'; END IF;
  RETURN NULL;
 END IF;
 IF TG_TABLE_NAME='profiled_result_heads' THEN a:=NEW.attempt_id;
 ELSIF TG_OP='INSERT' THEN a:=NEW.attempt_id;
 ELSE a:=OLD.attempt_id; END IF;
 IF EXISTS(SELECT 1 FROM profiled_settlement_evaluations WHERE disposition='accepted' AND (attempt_id=a OR (TG_OP<>'DELETE' AND attempt_id=NEW.attempt_id))) THEN
  IF TG_OP='UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'accepted report/source/ledger basis cannot change';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END

BEGIN
 IF TG_OP='TRUNCATE' THEN
  IF EXISTS(SELECT 1 FROM profiled_settlement_evaluations WHERE disposition='accepted') THEN RAISE EXCEPTION 'retained settlement messaging basis'; END IF;
  RETURN NULL;
 END IF;
 IF EXISTS(SELECT 1 FROM profiled_settlement_evaluations e JOIN agent_launch_bindings b USING(attempt_id) WHERE e.disposition='accepted' AND (settlement_sender_key(b.binding)=NEW.sender_key OR (TG_OP<>'INSERT' AND settlement_sender_key(b.binding)=OLD.sender_key))) THEN RAISE EXCEPTION 'accepted messaging-disabled basis immutable'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END

DECLARE e profiled_settlement_evaluations%ROWTYPE;
BEGIN
 IF current_setting('aq.settlement_owner',true) IS DISTINCT FROM 'aq.settlement-owner.1' OR NEW.settlement_operation_id IS NULL THEN RAISE EXCEPTION 'qualified settlement release owner required'; END IF;
 SELECT * INTO STRICT e FROM profiled_settlement_evaluations WHERE operation_id=NEW.settlement_operation_id;
 IF e.attempt_id<>NEW.attempt_id OR e.disposition<>'accepted' OR e.release_id<>NEW.release_id OR NEW.verified_at_ms<>e.created_at_ms
 OR NOT EXISTS(SELECT 1 FROM profiled_stopped_receipts WHERE attempt_id=NEW.attempt_id AND operation_id=NEW.stop_operation_id)
 THEN RAISE EXCEPTION 'release requires exact accepted evaluation'; END IF;
 RETURN NEW;
END

DECLARE profile TEXT;
BEGIN
 IF TG_TABLE_NAME='review_subjects' THEN
  IF TG_OP='UPDATE' AND NEW.subject_profile IS DISTINCT FROM OLD.subject_profile THEN RAISE EXCEPTION 'immutable review profile'; END IF;
  IF TG_OP='DELETE' AND OLD.subject_profile='source_and_effects_review_v1' THEN RAISE EXCEPTION 'retained combined review subject'; END IF;
  IF TG_OP='INSERT' AND NEW.subject_profile='source_and_effects_review_v1' AND current_setting('aq.settlement_owner',true) IS DISTINCT FROM 'aq.settlement-owner.1' THEN RAISE EXCEPTION 'combined review requires actual owner'; END IF;
 ELSE
  SELECT subject_profile INTO STRICT profile FROM review_subjects s JOIN human_decision_requests d USING(subject_digest) WHERE d.decision_id=NEW.decision_id;
  IF ((profile='code_review_v1' OR NEW.actor_id IS NULL) AND (NEW.combined_actor_digest IS NOT NULL OR NEW.combined_actor_revision IS NOT NULL))
   OR (profile='source_and_effects_review_v1' AND NEW.actor_id IS NOT NULL AND (NEW.combined_actor_digest IS NULL OR NEW.combined_actor_revision IS NULL OR current_setting('aq.settlement_owner',true) IS DISTINCT FROM 'aq.settlement-owner.1'))
  THEN RAISE EXCEPTION 'exact combined review actor owner required'; END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END

